import fs from 'node:fs';import path from 'node:path';import {createHash} from 'node:crypto';import {payloadHash} from '../execution/ledger.mjs';
import {advanceNoMaker} from '../live-paper/no-maker-paper.mjs';import {evaluateCanonicalNoCapacity} from '../live-paper/canonical-no-capacity.mjs';
const r=path.join(process.env.LOCALAPPDATA,'SigTradingCup/paper-runtime'),name='no-maker-tape-20261004-v1',dir=path.join(r,'no-maker-cohorts',name),bank=JSON.parse(fs.readFileSync(path.join(dir,'bank.json'))),bytes=fs.readFileSync(path.join(dir,'journal.jsonl'));
const sha=b=>createHash('sha256').update(b).digest('hex');if(bytes.at(-1)!==10)throw Error('Incomplete source; retry after append completes');
let sequence=0,previous='';const cases=[];for(const line of bytes.toString().trimEnd().split('\n')){const row=JSON.parse(line),{hash,...body}=row;if(row.sequence!==++sequence||row.previous!==previous||sha(JSON.stringify(body))!==hash)throw Error('Original journal integrity');previous=hash;
 const e=row.event;if(e.kind!=='book'||e.entryAllowed!==true)continue;const books=bank.legs.map(l=>row.state.paper.books[l.exchangeId]);
 const frame=evaluateCanonicalNoCapacity({review:bank.review,policy:bank.capacityPolicy,books,account:e.accountEligibility,now:e.availableAt});if(!frame.positiveConditionalCapacity)throw Error('Original admission differs');
 const omitted=books.find(b=>b.marketId!==e.book.marketId);const replay=advanceNoMaker(row.state.paper,{kind:'book',availableAt:e.availableAt,book:omitted,accountEligibility:e.accountEligibility,entryAllowed:true},bank);
 const newlyQuoted=Object.entries(replay.wallets).flatMap(([family,w])=>Object.values(w.quotes).filter(q=>!row.state.paper.wallets[family].quotes[q.id]).map(q=>({family,marketId:q.marketId,limit:q.limit,createdAt:q.createdAt,activationAt:q.activationAt,sourcePublicationHash:q.publicationHash})));
 if(newlyQuoted.length)cases.push({sequence:row.sequence,recordHash:hash,availableAt:e.availableAt,omittedMarketId:omitted.marketId,incomingMarketId:e.book.marketId,sourceVersions:books.map(b=>({marketId:b.marketId,versionKey:b.versionKey,publicationHash:b.publicationHash,requestStartedAt:b.requestStartedAt,receivedAt:b.receivedAt})),newlyQuoted});
}
const out={at:new Date().toISOString(),mode:'real_capture_source_order_admission_development_diagnostic',originalCohort:name,originalBankHash:payloadHash(bank),source:{bytes:bytes.length,sha256:sha(bytes),rows:sequence,tailHash:previous},missedCoherentFrames:cases.length,cases,
 fills:null,realizedPnl:null,profitabilityEstablished:false,limitations:['These are overlapping counterfactual admission checks, not independent trades or earnings.','Original frozen source/accounting is unchanged; the correction gets a new prospective cutoff.']};
fs.writeFileSync('data/no-maker-order-diagnostic-20261004.json',JSON.stringify(out,null,2));console.log(JSON.stringify({rows:sequence,missedCoherentFrames:cases.length,firstCase:cases[0],fills:null,realizedPnl:null}));
